import math

def count_divisors(n):
    """Counts the total number of positive divisors (tau(n))."""
    if n <= 0:
        return 0
    if n == 1:
        return 1

    count = 1
    temp = n
    i = 2
    while i * i <= temp:
        exponent = 0
        while temp % i == 0:
            exponent += 1
            temp //= i
        if exponent > 0:
            count *= (exponent + 1)
        i += 1
    if temp > 1:
        count *= 2
    return count

def d(n):
    """Calculates d(n) = number of divisors other than 1 and n."""
    if n <= 0:
        return -1
    tau = count_divisors(n)
    # d(n) = tau(n) - 2. If tau(n) = 1 (n=1), d(1) = 1 - 2 = -1. 
    # Based on the problem description (positive divisors other than 1 and itself), 
    # if n=1, the set is empty, so d(1)=0.
    if n == 1:
        return 0
    return tau - 2

# Search for the smallest a = d(n) = d(n+735)
# We search up to n = 1000 first.
max_n = 1000
results = {}

for n in range(1, max_n + 1):
    try:
        a = d(n)
        a_plus_735 = d(n + 735)

        if a == a_plus_735 and a >= 0:
            if a not in results:
                results[a] = []
            results[a].append(n)

    except Exception as e:
        # Safety catch for unexpected computational errors
        pass

# Sort results by the value of a
