print(f"Detailed results: {results}")

import math

def is_prime(k):
    """Checks if k is a prime number."""
    if k <= 1:
        return False
    if k <= 3:
        return True
    if k % 2 == 0 or k % 3 == 0:
        return False
    i = 5
    while i * i <= k:
        if k % i == 0 or k % (i + 2) == 0:
            return False
        i += 6
    return True

def is_product_of_two_distinct_primes(k):
    """Checks if k = p1 * p2 where p1 and p2 are distinct primes."""
    if k < 6:  # Smallest is 2*3 = 6
        return False

    # Find the smallest prime factor p1
    p1 = -1

    # Iterate through potential factors up to sqrt(k)
    limit = int(math.sqrt(k))

    # Check 2 separately
    if k % 2 == 0:
        p1 = 2
    else:
        # Check odd factors
        for i in range(3, limit + 1, 2):
            if k % i == 0:
                p1 = i
                break

    if p1 == -1:
        # k itself must be prime or 1, so it's not a product of two primes
        return False

    p2 = k // p1

    # Check if p1 and p2 are both prime and distinct
    if p1 != p2 and is_prime(p2):
        return True

    return False

