import math

def count_divisors(n):
    """Calculates tau(n), the total number of positive divisors of n."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

solutions = []
limit = 100000
target_tau = 4 # Since d(n) = tau(n) - 2, d(n)=2 implies tau(n)=4

print(f"Starting search for n <= {limit} such that tau(n) = tau(n+735) = {target_tau}")

for n in range(1, limit + 1):
    if count_divisors(n) == target_tau:
        n_plus_735 = n + 735
        if count_divisors(n_plus_735) == target_tau:
            solutions.append(n)
            print(f"Found solution: n = {n}")
            if len(solutions) >= 5:
                break

print("-" * 20)
if solutions:
    print(f"Total solutions found: {len(solutions)}")
    print("First 5 solutions (if available):")
